package com.imagine.martinhost;

import android.content.Context;
import java.util.*;

public final class GameCatalog {
    public static final class Game {
        public final String id,title,category,hostPrompt;
        public final boolean projector;
        public final int rounds;
        public Game(String id,String title,String category,boolean projector,int rounds,String hostPrompt){this.id=id;this.title=title;this.category=category;this.projector=projector;this.rounds=rounds;this.hostPrompt=hostPrompt;}
    }

    private static Game g(String id,String title,String category,boolean projector,String core){
        int rounds=18;
        String intro="Перед игрой ОБЯЗАТЕЛЬНО: 1) назови игру; 2) за 20-30 секунд объясни правила; 3) объясни баллы и окончание раунда; 4) дай один демонстрационный пример с правильным ответом, который потом не используется; 5) спроси «Правила понятны? Начинаем?»; 6) не начинай настоящее задание до подтверждения. В игре ровно "+rounds+" настоящих раундов. Сложность повышай плавно: раунды 1-6 простые и узнаваемые, 7-12 средние, 13-18 более сложные, но без узкоспециальных знаний. После каждого раунда называй текущий номер и коротко веди счёт. Не выдавай сразу несколько заданий: всегда только один раунд за раз и жди ответ. ";
        return new Game(id,title,category,projector,rounds,intro+core);
    }

    public static List<Game> all(){
        ArrayList<Game> x=new ArrayList<>();
        x.add(g("melody","Угадай мелодию","Музыка",false,"Используй реальные аудиофрагменты Яндекс Музыки. Для каждого настоящего раунда выбери известный трек по уровню сложности и после короткой фразы «Слушаем фрагмент» добавь служебный маркер [[PLAY_FRAGMENT:исполнитель название|6]]. Маркер вслух не объясняй. Не называй исполнителя или название до ответа. После фрагмента жди голосовой ответ. За правильного исполнителя ИЛИ название дай 1 балл, за оба сразу — 2 балла: спроси «Кто ответил?» и используй [[ASK_NAME_FOR_SCORE:1]] либо [[ASK_NAME_FOR_SCORE:2]]. Демонстрационный пример тоже запускай через PLAY_FRAGMENT, но баллы за него не начисляй."));
        x.add(g("chgk","Что? Где? Когда?","Викторина",false,"Задавай логические, бытовые и культурные вопросы, а не школьные тесты. Команде давай время обсудить. За правильный ответ — 1 балл и запрос имени ответившего."));
        x.add(g("quotes","Кто это сказал?","Цитаты",false,"Используй только общеизвестные и уверенно проверяемые короткие цитаты известных людей, актёров, писателей, музыкантов или персонажей кино. Игроки угадывают автора. Не приписывай человеку сомнительную цитату. За правильный ответ — 1 балл."));
        x.add(g("naughty_rhyme","Испорченность","Юмор",false,"Читай короткие авторские двусмысленные рифмованные загадки: кажется, что окончание будет пошлым, но правильное слово всегда невинное и логичное. Не используй оскорбления или графическое сексуальное содержание. За правильное слово — 1 балл."));
        x.add(g("two_stars","Две звезды — одно лицо","Знаменитости",true,"На проекторе показывается заранее подготовленное смешанное лицо двух известных людей. Один угаданный человек — 1 балл, оба — 3 балла. В каждом раунде жди один итоговый ответ."));
        x.add(g("transform","Что AI сделал со звездой?","Знаменитости",true,"На проекторе показывай подготовленные визуальные трансформации знаменитостей: возраст, другая эпоха, смешение двух звёзд, необычная профессия или сценический образ. Нужно узнать исходного человека; дополнительный балл можно дать за точное описание трансформации."));
        x.add(g("movie_ai","AI сломал фильм","Кино",true,"Показывай подготовленную AI-пародию на узнаваемый фильм или жанр без буквального копирования кадра. Игроки угадывают фильм или произведение. Один правильный ответ — 1 балл."));
        x.add(g("expert","Объяснение эксперта","Импровизация",true,"Покажи абсурдную AI-картинку с известным человеком или исторической фигурой и выбери игрока, который 30 секунд изображает эксперта и объясняет происходящее. После выступления коротко оцени по юмору и связности и начисли 1-3 балла."));
        x.add(g("ai_court","AI-суд","Импровизация",false,"Назначь обвиняемого, прокурора и адвоката. Обвинение должно быть полностью шуточным и безопасным. На каждый раунд давай короткий кейс, время сторонам и забавный приговор. Победившей стороне — 1 балл каждому выбранному представителю."));
        x.add(g("story","История по кругу","Импровизация",false,"Начни абсурдную историю, по очереди вызывай гостей продолжить её одной-двумя фразами. Один раунд — вклад одного гостя. После 18 вкладов кратко и смешно перескажи общую историю."));
        x.add(new Game("toast","Тост Мартина","Мартин",false,1,"Скажи один короткий персональный тост для Кати или компании, используя только подготовленные факты о гостях и имениннице. Не запускай игровой цикл и не начисляй баллы."));
        return Collections.unmodifiableList(x);
    }

    public static List<Game> available(Context c){
        boolean projector=c.getSharedPreferences("martin",0).getBoolean("projector",false);
        ArrayList<Game> out=new ArrayList<>();
        for(Game g:all()) if(!g.projector||projector) out.add(g);
        return out;
    }

    public static Game random(Context c,Set<String> recentlyUsed){
        ArrayList<Game> list=new ArrayList<>(available(c));
        if(recentlyUsed!=null) list.removeIf(g->recentlyUsed.contains(g.id));
        if(list.isEmpty()) list=new ArrayList<>(available(c));
        return list.get(new Random().nextInt(list.size()));
    }
}
